// Brute force: time O(n^3 + t log t) for t distinct triplets, space O(t)
class Solution {
public:
    int threeSum(vector<int>& nums) {
        int n = nums.size();
        set<array<int, 3>> found;
        for (int i = 0; i < n; i++)
            for (int j = i + 1; j < n; j++)
                for (int k = j + 1; k < n; k++)
                    if ((long long)nums[i] + nums[j] + nums[k] == 0) {
                        array<int, 3> t = {nums[i], nums[j], nums[k]};
                        sort(t.begin(), t.end());
                        found.insert(t);
                    }
        return (int)found.size();
    }
};

// Brute force: time O(4^n / sqrt(n)), space O(n)
class Solution {
public:
    int generateParenthesis(int n) {
        return go(n, 0, 0);
    }

private:
    int go(int n, int open, int close) {
        if (open == n && close == n) return 1;
        int total = 0;
        if (open < n) total += go(n, open + 1, close);
        if (close < open) total += go(n, open, close + 1);
        return total;
    }
};

// Brute force: time O(n * n!), space O(1)
class Solution {
public:
    int countPermutations(vector<int>& nums) {
        vector<int> a = nums;
        sort(a.begin(), a.end());
        int count = 0;
        do {
            count++;
        } while (next_permutation(a.begin(), a.end()));
        return count;
    }
};

// Brute force: time O(exponential), space O(target)
class Solution {
public:
    int combinationSum(vector<int>& candidates, int target) {
        return go(candidates, 0, target);
    }
private:
    int go(const vector<int>& c, int i, int remaining) {
        if (remaining == 0) return 1;
        if (i == (int)c.size() || remaining < 0) return 0;
        // use candidate i once more, or move on to the next candidate
        return go(c, i, remaining - c[i]) + go(c, i + 1, remaining);
    }
};

// Brute force: time O(n^2 * 256), space O(1)
class Solution {
public:
    int minWindow(string s, string t) {
        int n = s.size(), m = t.size();
        int need[256] = {};
        for (unsigned char c : t) need[c]++;
        // try window lengths from shortest to longest
        for (int len = m; len <= n; len++) {
            for (int st = 0; st + len <= n; st++) {
                int have[256] = {};
                for (int i = st; i < st + len; i++) have[(unsigned char)s[i]]++;
                bool ok = true;
                for (int c = 0; c < 256; c++) if (have[c] < need[c]) { ok = false; break; }
                if (ok) return len;
            }
        }
        return 0;
    }
};

// Brute force: time O(n^4 + u log u), space O(u) for u distinct quadruples
class Solution {
public:
    int fourSum(vector<int>& nums, int target) {
        int n = nums.size();
        set<vector<int>> found;
        for (int a = 0; a < n; a++)
            for (int b = a + 1; b < n; b++)
                for (int c = b + 1; c < n; c++)
                    for (int d = c + 1; d < n; d++)
                        if ((long long)nums[a] + nums[b] + nums[c] + nums[d] == target) {
                            vector<int> q = {nums[a], nums[b], nums[c], nums[d]};
                            sort(q.begin(), q.end());
                            found.insert(q);
                        }
        return (int)found.size();
    }
};
